html, body { margin: 0; min-height: 100%; -webkit-font-smoothing: antialiased; }

body {
    font-family: "Plus Jakarta Sans", -apple-system, BlinkMacSystemFont, sans-serif;
    font-size: 14px;
    color: var(--text);
    background: var(--bg);
    background-image: var(--body-bg-image);
    background-attachment: fixed;
    transition: background var(--transition), color var(--transition);
}

body.sidebar-open { overflow: hidden; }

h1, h2, h3, h4 {
    margin: 0;
    font-family: "Plus Jakarta Sans", sans-serif;
    font-weight: 700;
    letter-spacing: -0.01em;
    color: var(--text);
}

p { margin: 0; }

/* Animated mesh (dark only) */
@keyframes meshFloat {
    0%, 100% { transform: translate(0, 0) scale(1); }
    33% { transform: translate(30px, -20px) scale(1.05); }
    66% { transform: translate(-20px, 15px) scale(0.97); }
}

body::before {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    z-index: 0;
    display: none;
    background:
        radial-gradient(600px circle at 20% 30%, rgba(52,211,153,0.04), transparent),
        radial-gradient(500px circle at 80% 60%, rgba(96,165,250,0.03), transparent);
    animation: meshFloat 20s ease-in-out infinite;
}

[data-theme="dark"] body::before,
body[data-theme="dark"]::before {
    display: block;
}

