    min-height: 100vh;
    max-height: 100vh;
    overflow-y: auto;
    overflow-x: hidden;
    padding: 0;
    border-right: 1px solid var(--sidebar-line);
    border-radius: 0;
    background: var(--sidebar-bg);
    z-index: 50;
    scrollbar-width: none;
    -ms-overflow-style: none;
    box-shadow: none;
    border-top: none;
    border-bottom: none;
    border-left: none;
    backdrop-filter: none;
    transition: background 400ms ease;
}

[data-theme="dark"] .admin-sidebar {
    backdrop-filter: var(--blur);
    -webkit-backdrop-filter: var(--blur);
}

[data-theme="dark"] .admin-sidebar::after {
    content: "";
    position: absolute;
    top: 0;
    right: 0;
    width: 1px;
    height: 100%;
    background: linear-gradient(180deg, transparent, #34D399 20%, #60A5FA 50%, #A78BFA 80%, transparent);
    opacity: 0.25;
    pointer-events: none;
}

.admin-sidebar::-webkit-scrollbar { width: 0; height: 0; display: none; }

.admin-brand {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 22px 20px 18px;
    background: transparent;
    border: none;
    box-shadow: none;
    backdrop-filter: none;
    border-bottom: 1px solid var(--sidebar-line);
    border-radius: 0;
}

.admin-brand img {
    width: 42px;
    height: 42px;
    object-fit: contain;
    border-radius: var(--radius-sm);
    padding: 6px;
    background: rgba(255,255,255,0.1);
    flex-shrink: 0;
}

.admin-brand h1 {
    font-size: 0.82rem;
    font-family: "Plus Jakarta Sans", sans-serif;
    font-weight: 800;
    letter-spacing: 0.18em;
    color: #FFFFFF;
    text-transform: uppercase;
}

[data-theme="dark"] .admin-brand h1 {
    background: linear-gradient(135deg, #34D399, #06B6D4);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.admin-brand .eyebrow { color: rgba(255,255,255,0.45); font-size: 0.64rem; margin-bottom: 2px; }
.admin-brand .muted { color: rgba(255,255,255,0.38); font-size: 0.72rem; }

.eyebrow,
.section-kicker {
    margin: 0 0 4px;
    color: var(--muted);
    font-size: 0.7rem;
    font-weight: 700;
    letter-spacing: 0.12em;
    text-transform: uppercase;
}

.muted,
.section-copy,
.pagination-summary,
.form-note,
.employee-job {
    color: var(--muted);
    line-height: 1.6;
    font-size: 0.88rem;
}

.admin-sidebar-highlight {
    margin: 12px 12px 4px;
    padding: 14px 16px;
    border-radius: var(--radius-md);
    background: var(--sidebar-highlight-bg);
    border: 1px solid var(--sidebar-highlight-border);
    color: rgba(255,255,255,0.9);
    box-shadow: none;
    backdrop-filter: none;
}

.admin-sidebar-highlight .eyebrow { color: rgba(255,255,255,0.4); font-size: 0.63rem; }
.admin-sidebar-highlight .muted { color: rgba(255,255,255,0.5); font-size: 0.78rem; }
.admin-sidebar-highlight strong { display: block; font-size: 0.9rem; margin-bottom: 4px; color: rgba(255,255,255,0.95); }

[data-theme="dark"] .admin-sidebar-highlight { color: #34D399; }
[data-theme="dark"] .admin-sidebar-highlight strong { color: #34D399; }

/* Nav */
.admin-nav {
    display: flex;
    flex-direction: column;
    gap: 2px;
    padding: 14px 10px;
    flex: 1;
    position: relative;
    z-index: 2;
}

.admin-sidebar-footer {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: auto;
    padding: 14px 12px 22px;
    border-top: 1px solid var(--sidebar-line);
    position: relative;
    z-index: 2;
}

.admin-link,
.soft-btn,
.ghost-link,
.danger-btn,
.primary-btn,
.mini-btn {
    border-radius: var(--radius-sm);
    font: inherit;
    font-weight: 600;
    transition: all var(--transition);
    cursor: pointer;
}

.admin-link {
    position: relative;
    display: flex;
    align-items: center;
    gap: 12px;
    border: none;
    color: var(--sidebar-text);
    padding: 10px 14px;
    text-align: left;
    cursor: pointer;
    text-decoration: none;
    background: transparent;
    font-size: 0.88rem;
    font-weight: 500;
    border-radius: var(--radius-sm);
    overflow: hidden;
    width: 100%;
    pointer-events: auto;
    touch-action: manipulation;
    -webkit-appearance: none;
    appearance: none;
    -webkit-tap-highlight-color: transparent;
    z-index: 2;
}

.admin-link svg {
    flex-shrink: 0;
    opacity: 0.55;
    transition: all var(--transition);
}

.admin-link:hover {
    color: var(--sidebar-text-active);
    background: var(--sidebar-surface);
    transform: translateX(3px);
    box-shadow: none;
}

.admin-link:hover svg { opacity: 0.9; }

[data-theme="dark"] .admin-link:hover svg { color: #34D399; }

.admin-link.active {
    color: var(--sidebar-text-active);
    background: var(--sidebar-active-bg);
    font-weight: 600;
    transform: none;
}

.admin-link.active svg { opacity: 1; }

[data-theme="dark"] .admin-link.active svg { color: #34D399; }

.admin-link.active::before {
    content: "";
    position: absolute;
    left: 0;
    top: 50%;
    transform: translateY(-50%);
    width: 3px;
    height: 55%;
    border-radius: 0 4px 4px 0;
    background: var(--primary);
}

[data-theme="dark"] .admin-link.active::before {
    background: #34D399;
}

.ghost-link,
.danger-btn {
    border: none;
    padding: 10px 14px;
    text-align: left;
    text-decoration: none;
    background: transparent;
}

.ghost-link {
    display: flex;
    align-items: center;
    gap: 10px;
    color: rgba(255,255,255,0.55);
    font-size: 0.84rem;
}

.ghost-link:hover { color: #fff; }

.ghost-link svg,
.danger-btn svg { flex-shrink: 0; opacity: 0.6; }

.admin-profile {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 12px 14px;
    border-radius: var(--radius-md);
    background: var(--sidebar-surface);
    border: 1px solid var(--sidebar-line);
    color: #fff;
    box-shadow: none;
    backdrop-filter: none;
}

.admin-profile strong { font-size: 0.86rem; color: #fff; }

.role-pill,
.hero-badge,
.status-pill {
    display: inline-flex;
    align-items: center;
    width: fit-content;
    padding: 4px 10px;
    border-radius: 99px;
    font-size: 0.7rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

.role-pill { background: rgba(255,255,255,0.1); color: rgba(255,255,255,0.9); }
.hero-badge { background: var(--primary-light); color: var(--primary); }

.danger-btn {
    display: flex;
    align-items: center;
    gap: 10px;
    color: #FCA5A5;
    background: rgba(220,38,38,0.12);
    border-radius: var(--radius-sm);
    padding: 8px 14px;
    max-width: 300px;
}

.danger-btn:hover { background: rgba(220,38,38,0.2); }

[data-theme="dark"] .danger-btn { color: #FB7185; background: rgba(251,113,133,0.12); }

