    border-radius: var(--radius-xl);
    background: var(--bg-card);
    border: 1px solid var(--line);
    box-shadow: var(--shadow-sm);
    backdrop-filter: var(--card-backdrop);
    transition: all var(--transition);
}

.admin-topbar .eyebrow { color: var(--accent); font-size: 0.68rem; margin-bottom: 2px; }

.admin-topbar-title { font-size: 1.5rem; font-weight: 800; letter-spacing: -0.02em; }

.admin-topbar-actions {
    display: flex;
    align-items: center;
    gap: 12px;
}

.admin-mobile-controls {
    display: none;
    margin-top: 14px;
    gap: 10px;
    align-items: center;
    flex-wrap: wrap;
}

.admin-mobile-switcher {
    display: flex;
    flex-direction: column;
    gap: 6px;
    min-width: min(100%, 280px);
    color: var(--text-secondary);
    font-size: 0.76rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

.admin-mobile-switcher select {
    min-width: 220px;
}

.admin-topbar-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

.admin-topbar-tags span {
    display: inline-flex;
    align-items: center;
    padding: 6px 12px;
    border-radius: 99px;
    background: var(--topbar-tags-bg);
    color: var(--topbar-tags-color);
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    border: 1px solid transparent;
    transition: all var(--transition);
}

[data-theme="dark"] .admin-topbar-tags span {
    border-color: var(--line);
}

.admin-topbar-tags span:hover {
    background: var(--primary-dim);
    color: var(--primary);
}

