    align-items: center;
    border-radius: var(--radius-2xl);
    background: var(--bg-card);
    border: 1px solid var(--line);
    box-shadow: var(--shadow-md);
    backdrop-filter: var(--card-backdrop);
    overflow: hidden;
    transition: all var(--transition);
}

[data-theme="dark"] .admin-hero::before {
    content: "";
    position: absolute;
    top: -40%;
    right: -15%;
    width: 350px;
    height: 350px;
    background: radial-gradient(circle, rgba(52,211,153,0.06), transparent 70%);
    pointer-events: none;
}

.admin-hero h2 {
    font-size: clamp(1.6rem, 3vw, 2.2rem);
    font-weight: 800;
    letter-spacing: -0.02em;
    line-height: 1.25;
    position: relative;
    z-index: 1;
}

.lead {
    max-width: 56ch;
    color: var(--text-secondary);
    line-height: 1.7;
    font-size: 0.92rem;
    margin-top: 8px;
    position: relative;
    z-index: 1;
}

.hero-accent {
    position: relative;
    z-index: 1;
    align-self: center;
    justify-self: end;
    width: min(100%, 320px);
    padding: 24px;
    border-radius: var(--radius-xl);
    background: var(--surface-glass);
    border: 1px solid var(--line);
    box-shadow: var(--shadow-md);
    backdrop-filter: none;
}

.hero-accent strong { display: block; margin: 10px 0 6px; font-size: 1.15rem; }
.hero-accent .section-copy { font-size: 0.84rem; }

