    gap: 16px;
}
.metric-tile {
    position: relative;
    padding: 24px;
    background: linear-gradient(135deg, var(--bg-card) 0%, var(--surface-glass) 100%);
    border: 1px solid var(--line);
    box-shadow: var(--shadow-md);
    backdrop-filter: var(--card-backdrop);
    overflow: hidden;
    display: flex;
    flex-direction: column;
    justify-content: center;
}

/* Accent lines or borders for different states */
.metric-tile::after {
    content: "";
    position: absolute;
    bottom: 0;
    left: 0;
    width: 0;
    height: 3px;
    background: var(--primary);
    transition: width 0.4s ease-out;
}

.metric-tile:hover::after {
    width: 100%;
}

.metric-tile:hover {
    box-shadow: var(--shadow-lg);
    border-color: var(--primary-dim);
    transform: translateY(-4px) scale(1.01);
}

[data-theme="dark"] .metric-tile {
    background: linear-gradient(145deg, rgba(30, 36, 58, 0.6) 0%, rgba(22, 27, 45, 0.5) 100%);
    box-shadow: inset 0 1px 1px rgba(255,255,255,0.05);
}

[data-theme="dark"] .metric-tile:hover {
    box-shadow: 0 15px 30px rgba(0,0,0,0.5), inset 0 1px 1px rgba(255,255,255,0.1);
    border-color: rgba(255,255,255,0.15);
}

[data-theme="dark"] .metric-tile:nth-child(2n)::after { background: linear-gradient(90deg, #34D399, #06B6D4); }
[data-theme="dark"] .metric-tile:nth-child(2n+1)::after { background: linear-gradient(90deg, #F59E0B, #EF4444); }
[data-theme="dark"] .metric-tile:nth-child(3n)::after { background: linear-gradient(90deg, #A78BFA, #EC4899); }

.metric-tile span {
    color: var(--text-secondary);
    font-size: 0.85rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-bottom: 6px;
    position: relative;
    z-index: 1;
}

.metric-tile strong {
    display: block;
    margin-top: 4px;
    font-size: 1.8rem;
    font-weight: 800;
    letter-spacing: -0.02em;
    color: var(--text);
    position: relative;
    z-index: 1;
    line-height: 1.1;
}

.metric-tile.profit-positive strong { color: var(--success); }

[data-theme="dark"] .metric-tile.profit-positive strong {
    background: linear-gradient(135deg, #34D399, #10B981);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.metric-tile.profit-negative strong { color: var(--danger); }

