    border: 1px solid var(--line);
    box-shadow: var(--shadow-sm);
    backdrop-filter: var(--card-backdrop);
    transition: all var(--transition);
}

.admin-card:hover { box-shadow: var(--shadow-md); }

.section-head { display: flex; gap: 16px; justify-content: space-between; align-items: flex-start; flex-wrap: wrap; }
.section-head h3 { font-size: 1.25rem; font-weight: 700; }

.section-actions,
.table-actions,
.pagination-actions,
.form-actions,
.orders-toolbar {
    display: flex; gap: 8px; flex-wrap: wrap; align-items: center;
}

.orders-view-switch {
    display: inline-flex;
    gap: 8px;
    padding: 6px;
    border-radius: 999px;
    background: var(--bg-alt);
    border: 1px solid var(--line);
    box-shadow: var(--shadow-sm);
}

.orders-view-switch .soft-btn {
    border-radius: 999px;
    padding-inline: 16px;
    background: transparent;
    border: 1px solid transparent;
}

.orders-view-switch .soft-btn.is-active {
    background: var(--primary);
    color: #fff;
    border-color: var(--primary);
    box-shadow: var(--shadow-sm);
}

