    background: var(--surface-glass);
    color: var(--text);
    border-radius: var(--radius-sm);
    padding: 10px 14px;
    font: inherit;
    font-size: 0.88rem;
    outline: none;
    transition: all var(--transition);
}

.search-input:focus,
.admin-form input:focus,
.admin-form select:focus,
.table-input:focus,
.inline-select:focus {
    border-color: var(--primary);
    box-shadow: 0 0 0 3px var(--primary-dim);
}

[data-theme="dark"] .search-input:focus,
[data-theme="dark"] .admin-form input:focus,
[data-theme="dark"] .admin-form select:focus {
    box-shadow: 0 0 0 3px var(--primary-dim), 0 0 16px rgba(52,211,153,0.06);
}

.search-input::placeholder { color: var(--muted); opacity: 0.7; }
.admin-form { display: flex; flex-direction: column; gap: 16px; }
.form-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 14px; }
.form-grid .full { grid-column: 1 / -1; }

.admin-form label,
.orders-date-filter {
    display: flex; flex-direction: column; gap: 6px;
    color: var(--text-secondary); font-size: 0.82rem; font-weight: 600;
}

.admin-form select option { background: var(--select-option-bg); color: var(--text); }

