    min-height: 42px;
    font-weight: 700;
    font-size: 0.88rem;
    border-radius: var(--radius-sm);
    box-shadow: var(--btn-primary-shadow);
    transition: all var(--transition);
}

.primary-btn:hover {
    filter: brightness(1.08);
    transform: translateY(-1px);
}

[data-theme="dark"] .primary-btn:hover {
    box-shadow: 0 0 28px rgba(52,211,153,0.22);
}

.soft-btn, .mini-btn {
    border: 1px solid var(--line);
    background: var(--surface-glass);
    color: var(--text-secondary);
    padding: 8px 14px;
    font-size: 0.82rem;
    border-radius: var(--radius-sm);
}

.soft-btn:hover, .mini-btn:hover {
    background: var(--bg-hover);
    border-color: var(--line-strong);
    color: var(--text);
}

.mini-btn { padding: 6px 12px; font-size: 0.78rem; }

.mini-btn.bad { color: var(--danger); border-color: rgba(220,38,38,0.15); background: var(--danger-bg); }
.mini-btn.bad:hover { background: rgba(220,38,38,0.16); }
.mini-btn.warn { color: var(--warning); border-color: rgba(217,119,6,0.15); background: var(--warning-bg); }

