    backdrop-filter: var(--card-backdrop);
    box-shadow: none;
}

.admin-table { width: 100%; min-width: 680px; border-collapse: collapse; }

.admin-table th,
.admin-table td {
    padding: 12px 16px;
    border-bottom: 1px solid var(--line);
    text-align: left;
    font-size: 0.85rem;
    vertical-align: middle;
}

.admin-table th {
    color: var(--muted);
    font-weight: 700;
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    background: var(--table-header-bg);
    border-bottom: 1px solid var(--line-strong);
    position: sticky;
    top: 0;
    z-index: 1;
}

.admin-table tbody tr { transition: background var(--transition); }
.admin-table tbody tr:hover { background: var(--bg-hover); }
.admin-table tbody tr:last-child td { border-bottom: none; }
.admin-table td small { color: var(--muted); }
.admin-table tbody tr.is-selected-client-row { background: rgba(37, 99, 235, 0.08); }

.status-pill.ok { background: var(--success-bg); color: var(--success); }
.status-pill.warn { background: var(--warning-bg); color: var(--warning); }
.status-pill.bad { background: var(--danger-bg); color: var(--danger); }

