#adminAccountSummary.inline-stats { grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); }
#adminAccountSummary .inline-stat { min-height: 100px; }
#adminAccountSummary .inline-stat span { display: block; line-height: 1.35; }
#adminAccountSummary .inline-stat strong { font-size: 1rem; line-height: 1.35; }

.inline-stat {
    border-radius: var(--radius-lg);
    padding: 20px;
    min-width: 0;
    overflow: hidden;
    background: linear-gradient(135deg, var(--bg-card) 0%, var(--surface-glass) 100%);
    border: 1px solid var(--line);
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    box-shadow: var(--shadow-sm);
    backdrop-filter: var(--card-backdrop);
    display: flex;
    flex-direction: column;
    justify-content: center;
}

[data-theme="dark"] .inline-stat {
    background: linear-gradient(145deg, rgba(30, 36, 58, 0.6) 0%, rgba(22, 27, 45, 0.5) 100%);
    box-shadow: inset 0 1px 1px rgba(255,255,255,0.05);
}

.inline-stat:hover { 
    border-color: var(--primary-dim); 
    transform: translateY(-3px) scale(1.02); 
    box-shadow: var(--shadow-md); 
}

[data-theme="dark"] .inline-stat:hover {
    box-shadow: 0 8px 20px rgba(0,0,0,0.4), inset 0 1px 1px rgba(255,255,255,0.1);
    border-color: rgba(255,255,255,0.15);
}

.inline-stat span { 
    color: var(--text-secondary); 
    font-size: 0.8rem; 
    font-weight: 600; 
    text-transform: uppercase; 
    letter-spacing: 0.05em; 
    margin-bottom: 4px;
}

.inline-stat strong {
    display: block; 
    margin-top: 6px; 
    font-size: 1.4rem; 
    font-weight: 800; 
    line-height: 1.15;
    overflow-wrap: anywhere; 
    word-break: break-word; 
    hyphens: auto; 
    color: var(--text);
}

