.employee-card {
    position: relative;
    border-radius: var(--radius-xl);
    padding: 20px;
    display: flex;
    flex-direction: column;
    gap: 12px;
    background: var(--bg-card);
    border: 1px solid var(--line);
    box-shadow: var(--shadow-sm);
    backdrop-filter: var(--card-backdrop);
    transition: all var(--transition);
    overflow: hidden;
}

[data-theme="dark"] .employee-card::before {
    content: "";
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: linear-gradient(135deg, #60A5FA, #34D399);
    opacity: 0;
    transition: opacity var(--transition);
}

.employee-card:hover {
    box-shadow: var(--shadow-lg);
    border-color: var(--line-strong);
    transform: translateY(-3px);
}

[data-theme="dark"] .employee-card:hover::before { opacity: 1; }

.employee-card-head { display: flex; justify-content: space-between; gap: 8px; align-items: center; }
.employee-card h4 { font-size: 1.15rem; font-weight: 700; }
.employee-label { margin: 0; color: var(--muted); font-size: 0.72rem; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; }

.employee-card .role-pill {
    background: var(--primary-dim);
    color: var(--primary);
}

.employee-meta {
    display: grid; grid-template-columns: 1fr 1fr; gap: 12px;
    padding-top: 12px; border-top: 1px solid var(--line);
}

.employee-salary {
    display: block; margin-top: 6px;
    font-size: 1.15rem; font-weight: 800;
    color: var(--salary-color);
}

[data-theme="dark"] .employee-salary {
    background: linear-gradient(135deg, #34D399, #06B6D4);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.employee-contact { margin: 6px 0 0; line-height: 1.5; font-size: 0.82rem; color: var(--text-secondary); }

