.chart-bar-card { display: flex; flex-direction: column; gap: 6px; align-items: center; }
.chart-bar-card strong { font-size: 0.82rem; font-weight: 700; color: var(--text); }
.chart-bar-card span { font-size: 0.72rem; color: var(--muted); }
.chart-bar-wrap { width: 100%; height: 120px; display: flex; align-items: end; padding: 0 8px; border-radius: var(--radius-sm); background: var(--surface-glass); }
.chart-bar { width: 100%; border-radius: 6px 6px 2px 2px; background: var(--chart-gradient); box-shadow: var(--chart-glow); transition: height 600ms cubic-bezier(0.34, 1.56, 0.64, 1); }

