.admin-account-hero h3 { font-size: clamp(1.4rem, 2.6vw, 2rem); font-weight: 800; }

.admin-account-hero-badge {
    padding: 24px;
    border-radius: var(--radius-xl);
    border: none;
    background: linear-gradient(135deg, var(--primary), var(--primary-deep));
    color: #FFFFFF;
    box-shadow: var(--shadow-lg);
}

[data-theme="dark"] .admin-account-hero-badge {
    background: linear-gradient(135deg, #34D399, #06B6D4);
    color: #0F1117;
    box-shadow: 0 12px 32px rgba(52,211,153,0.2);
}

.admin-account-hero-badge .hero-badge { background: rgba(255,255,255,0.15); color: inherit; }
.admin-account-hero-badge strong { display: block; margin: 10px 0 6px; font-size: 1.25rem; }
.admin-account-hero-badge .muted { color: rgba(255,255,255,0.6); }

[data-theme="dark"] .admin-account-hero-badge .muted { color: rgba(15,17,23,0.5); }

.face-profile-list { display: flex; flex-direction: column; gap: 10px; }

.admin-face-composer { display: grid; grid-template-columns: 1fr auto; gap: 12px; align-items: end; padding: 16px; border-radius: var(--radius-md); background: var(--surface-glass); border: 1px solid var(--line); }
.admin-face-label { display: flex; flex-direction: column; gap: 6px; color: var(--text-secondary); font-size: 0.82rem; font-weight: 600; }
.admin-face-composer-actions { display: flex; align-items: center; justify-content: flex-end; }

.admin-inline-face-capture { display: flex; flex-direction: column; gap: 14px; padding: 20px; border-radius: var(--radius-xl); border: 1px solid var(--line); background: var(--bg-card); backdrop-filter: var(--card-backdrop); box-shadow: var(--shadow-lg); }
.admin-inline-face-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 14px; }
.admin-inline-face-head h4 { font-size: 1.15rem; }
.admin-inline-camera-shell { margin-top: 0; min-height: 380px; }
.admin-inline-face-actions { margin-top: 0; }

.face-profile-card, .face-modal-card { background: var(--bg-card); border: 1px solid var(--line); backdrop-filter: var(--card-backdrop); box-shadow: var(--shadow-sm); }
.face-profile-card { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 16px 20px; border-radius: var(--radius-xl); transition: all var(--transition); }
.face-profile-card:hover { box-shadow: var(--shadow-md); border-color: var(--line-strong); }
.face-profile-card h4 { font-size: 1.1rem; margin-top: 6px; }
.face-profile-card-copy { display: flex; flex-direction: column; gap: 2px; }
.face-profile-card-actions { display: flex; flex-direction: column; gap: 8px; align-items: flex-end; }
.face-profile-card.empty { display: flex; flex-direction: column; min-height: 120px; align-items: flex-start; padding: 24px; }

.face-profile-chip, .face-profile-id { display: inline-flex; align-items: center; width: fit-content; border-radius: 99px; font-size: 0.72rem; font-weight: 700; letter-spacing: 0.04em; }
.face-profile-chip { padding: 4px 10px; color: var(--primary); background: var(--primary-light); }
.face-profile-id { padding: 4px 8px; color: var(--muted); background: var(--surface-glass); }

.face-modal-card { width: min(100%, 640px); border-radius: var(--radius-2xl); padding: 28px; }
.face-modal-card h3 { font-size: clamp(1.5rem, 2.5vw, 2rem); }
.camera-shell { position: relative; margin-top: 12px; min-height: 340px; overflow: hidden; border-radius: var(--radius-xl); border: 1px solid var(--line); background: var(--bg-alt); }
.face-video { display: block; width: 100%; aspect-ratio: 4/3; min-height: 340px; object-fit: cover; transform: scaleX(-1); }
.camera-frame { position: absolute; inset: 16px; border: 2px solid rgba(255,255,255,0.7); border-radius: var(--radius-2xl); box-shadow: inset 0 0 0 999px rgba(0,0,0,0.15); pointer-events: none; }
.camera-frame::before { content: ""; position: absolute; inset: 12% 22%; border: 2px solid var(--accent); border-radius: 999px; box-shadow: 0 0 0 999px rgba(0,0,0,0.06); }
.face-canvas { display: none; }
.face-modal-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 14px; }

