    background: linear-gradient(135deg, #34D399, #06B6D4);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}
.orders-date-filter span { font-weight: 600; font-size: 0.78rem; color: var(--muted); }

.payment-modal {
    position: fixed;
    inset: 0;
    z-index: 120;
    display: grid;
    place-items: center;
    padding: 24px;
}

.payment-modal-backdrop {
    position: absolute;
    inset: 0;
    background: rgba(15, 23, 42, 0.48);
    backdrop-filter: blur(8px);
}

.payment-modal-dialog {
    position: relative;
    width: min(100%, 560px);
    border-radius: var(--radius-2xl);
    background: var(--bg-card);
    border: 1px solid var(--line);
    box-shadow: var(--shadow-xl);
    padding: 28px;
    display: flex;
    flex-direction: column;
    gap: 20px;
}

.payment-modal-head,
.payment-modal-actions {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
}

.payment-modal-head h3 {
    font-size: 1.35rem;
    font-weight: 800;
}

.payment-modal-body {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.payment-modal-stats {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
}

.payment-stat-card {
    padding: 16px 18px;
    border-radius: var(--radius-lg);
    border: 1px solid var(--line);
    background: linear-gradient(135deg, var(--bg-hover), var(--bg-card));
    box-shadow: var(--shadow-sm);
}

.payment-stat-card span {
    display: block;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--muted);
    margin-bottom: 6px;
    font-weight: 700;
}

.payment-stat-card strong {
    display: block;
    font-size: 1.2rem;
    font-weight: 800;
    color: var(--text);
}

.payment-modal-field {
    display: flex;
    flex-direction: column;
    gap: 8px;
    color: var(--text-secondary);
    font-size: 0.86rem;
    font-weight: 600;
}

.payment-modal-input {
    min-height: 54px;
    font-size: 1.05rem;
    font-weight: 700;
}

.payment-modal-actions {
    justify-content: flex-end;
}

.payment-modal-actions .soft-btn,
.payment-modal-actions .primary-btn {
    min-width: 160px;
}

.overview-lock-modal {
    position: fixed;
    inset: 0;
    z-index: 140;
    display: grid;
    place-items: center;
    padding: 24px;
}

.overview-lock-backdrop {
    position: absolute;
    inset: 0;
    background: rgba(15, 23, 42, 0.48);
    backdrop-filter: blur(8px);
}

.overview-lock-dialog {
    position: relative;
    width: min(100%, 520px);
    border-radius: var(--radius-2xl);
    background:
        radial-gradient(circle at top right, rgba(22, 163, 74, 0.12), transparent 34%),
        linear-gradient(180deg, var(--bg-card) 0%, var(--bg-hover) 100%);
    border: 1px solid var(--line);
    box-shadow: var(--shadow-xl);
    padding: 28px;
    display: flex;
    flex-direction: column;
    gap: 20px;
}

.overview-lock-head,
.overview-lock-actions {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
}

.overview-lock-head h3 {
    font-size: 1.35rem;
    font-weight: 800;
    color: var(--text);
}

.overview-lock-body {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.overview-lock-field {
    display: flex;
    flex-direction: column;
    gap: 8px;
    color: var(--text-secondary);
    font-size: 0.86rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.overview-lock-input {
    min-height: 56px;
    font-size: 1.05rem;
    font-weight: 700;
    border-radius: 18px;
    border: 1px solid rgba(22, 101, 52, 0.18);
    background: rgba(255, 255, 255, 0.94);
}

.overview-lock-input:focus {
    border-color: rgba(22, 163, 74, 0.55);
    box-shadow: 0 0 0 4px rgba(34, 197, 94, 0.12);
}

.overview-lock-actions {
    justify-content: flex-end;
}

.overview-lock-actions .soft-btn,
.overview-lock-actions .primary-btn {
    min-width: 150px;
}

