.mobile-sidebar-toggle {
    position: fixed; top: 12px; left: 12px; z-index: 70;
    border: 1px solid var(--line); width: 44px; height: 44px;
    border-radius: var(--radius-sm); padding: 0; color: white;
    background: var(--bg-card);
    box-shadow: var(--shadow-lg); cursor: pointer;
}

[data-theme="dark"] .mobile-sidebar-toggle {
    background: rgba(15,17,23,0.85);
    backdrop-filter: var(--blur);
}

.mobile-sidebar-toggle-inline { border: none; border-radius: 99px; padding: 8px 14px; font: inherit; font-size: 0.82rem; font-weight: 700; color: #fff; background: var(--primary); cursor: pointer; }

.mobile-sidebar-backdrop { position: fixed; inset: 0; z-index: 49; background: rgba(0,0,0,0.4); opacity: 0; pointer-events: none; transition: opacity 250ms ease; }
[data-theme="dark"] .mobile-sidebar-backdrop { backdrop-filter: blur(6px); background: rgba(0,0,0,0.6); }
.mobile-sidebar-backdrop.active { opacity: 1; pointer-events: auto; }

.mobile-sidebar-close { border: none; border-radius: 99px; padding: 8px 14px; font: inherit; font-size: 0.82rem; font-weight: 700; color: #fff; background: var(--primary); cursor: pointer; }

.hamburger-toggle { display: none; align-items: center; justify-content: center; flex-direction: column; gap: 5px; }
.hamburger-toggle span { display: block; width: 20px; height: 2px; border-radius: 99px; background: var(--text); transition: transform 200ms ease, opacity 200ms ease; }
[data-theme="dark"] .hamburger-toggle span { background: #fff; }
body.sidebar-open .hamburger-toggle span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
body.sidebar-open .hamburger-toggle span:nth-child(2) { opacity: 0; }
body.sidebar-open .hamburger-toggle span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

