    .admin-main { margin-left: 260px; padding: 20px 20px 32px; }
    .metrics-grid { grid-template-columns: repeat(2, 1fr); }
    .admin-grid.two, .admin-hero, .admin-account-hero { grid-template-columns: 1fr; }
    .hero-accent { justify-self: stretch; width: 100%; }
    .inline-stats { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 940px) {
    .admin-shell { padding: 0 !important; }
    #adminSidebar { display: none; }
    .mobile-admin-sidebar-panel { display: flex; }
    .admin-sidebar {
        position: fixed; top: 0; left: -320px; bottom: 0; z-index: 60;
        width: 300px; max-width: 85vw;
        height: 100dvh; max-height: 100dvh; min-height: 100dvh; margin: 0;
        overflow-y: auto; overflow-x: hidden;
        opacity: 0; visibility: hidden; pointer-events: none;
        -webkit-overflow-scrolling: touch;
        overscroll-behavior: contain;
        transform: none;
        transition: left 300ms cubic-bezier(0.4, 0, 0.2, 1), opacity 220ms ease;
        border-radius: 0; box-shadow: var(--shadow-xl);
    }
    .admin-sidebar.mobile-open { left: 0; opacity: 1; visibility: visible; z-index: 60; pointer-events: auto; }
    body.sidebar-open .admin-main { pointer-events: none; }
    body.sidebar-open .admin-sidebar,
    body.sidebar-open .admin-sidebar * { pointer-events: auto; }
    .mobile-sidebar-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 16px 20px; border-bottom: 1px solid var(--sidebar-line); color: var(--sidebar-text-active); }
    .admin-main { padding: 64px 16px 24px; margin-left: 0; }
    .admin-topbar { flex-direction: column; align-items: flex-start; gap: 14px; }
    .mobile-sidebar-toggle, .mobile-sidebar-toggle-inline { display: inline-flex; align-items: center; justify-content: center; }
    .admin-mobile-controls { display: flex; }
    .mobile-sidebar-close { display: inline-flex; align-items: center; justify-content: center; }
    .metrics-grid { grid-template-columns: repeat(2, 1fr); }
    .admin-grid.two { grid-template-columns: 1fr; }
}

@media (max-width: 640px) {
    .admin-sidebar { left: -100vw; width: 100vw; max-width: 100vw; border-radius: 0; padding: 0; }
    .admin-topbar, .admin-card, .admin-hero, .face-modal-card { border-radius: var(--radius-lg); padding: 16px; }
    .metric-tile { border-radius: var(--radius-md); padding: 14px; }
    .metric-tile strong { font-size: 1.25rem; }
    .metrics-grid { grid-template-columns: 1fr 1fr; gap: 10px; }
    .inline-stats, .form-grid, .employee-meta, .face-modal-actions { grid-template-columns: 1fr; }
    .admin-face-composer { grid-template-columns: 1fr; }
    .admin-face-composer-actions { justify-content: stretch; }
    .admin-face-composer-actions .primary-btn { width: 100%; }
    .admin-inline-face-head { flex-direction: column; }
    .face-profile-card { flex-direction: column; align-items: flex-start; }
    .camera-shell, .admin-inline-camera-shell, .face-video { min-height: 260px; }
    .admin-main { padding: 60px 10px 20px; gap: 14px; }
    .admin-mobile-controls { flex-direction: column; align-items: stretch; }
    .admin-mobile-switcher,
    .admin-mobile-switcher select,
    .mobile-sidebar-toggle-inline { width: 100%; }
    .admin-hero { grid-template-columns: 1fr; }
    .admin-hero h2 { font-size: 1.35rem; }
    .section-head { flex-direction: column; }
    .section-head h3 { font-size: 1.1rem; }
    .employee-card-grid { grid-template-columns: 1fr; }
    .admin-topbar-title { font-size: 1.2rem; }
    .admin-topbar-tags { gap: 6px; }
    .admin-topbar-tags span { font-size: 0.65rem; padding: 4px 8px; }
    .table-actions { flex-wrap: wrap; }
    .orders-toolbar { flex-direction: column; align-items: stretch; }
    .orders-toolbar .search-input, .orders-toolbar .orders-filter, .orders-toolbar .primary-btn, .orders-toolbar .soft-btn { width: 100%; }
    .orders-view-switch { width: 100%; justify-content: stretch; }
    .orders-view-switch .soft-btn { flex: 1 1 0; text-align: center; }
    .payment-modal { padding: 12px; }
    .payment-modal-dialog { padding: 18px; border-radius: var(--radius-lg); }
    .payment-modal-head, .payment-modal-actions { flex-direction: column; align-items: stretch; }
    .payment-modal-stats { grid-template-columns: 1fr; }
    .payment-modal-actions .soft-btn, .payment-modal-actions .primary-btn { width: 100%; min-width: 0; }
    .overview-lock-dialog { padding: 18px; border-radius: var(--radius-lg); }
    .overview-lock-head, .overview-lock-actions { flex-direction: column; align-items: stretch; }
    .overview-lock-actions .soft-btn, .overview-lock-actions .primary-btn { width: 100%; min-width: 0; }
    .theme-toggle { width: 40px; height: 40px; }
    .theme-toggle .icon-sun, .theme-toggle .icon-moon { width: 22px; height: 22px; }
}

