    display: flex;
    flex-direction: column;
    gap: 16px;
    padding: 18px;
    border: 1px solid #9eb7d6;
    border-radius: 18px;
    background:
        linear-gradient(180deg, rgba(219, 233, 248, 0.95) 0%, rgba(245, 249, 255, 0.95) 82%),
        #edf4fb;
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.85), 0 18px 36px rgba(41, 72, 117, 0.12);
}

.invoice-workspace-sheet.is-wholesale {
    border-color: #7fa1cd;
}

.invoice-workspace-sheet.is-detail {
    border-color: #a9bccf;
}

.invoice-software-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
}

.invoice-software-badge {
    min-width: 96px;
    padding: 8px 12px;
    border-radius: 10px;
    background: linear-gradient(180deg, #1d67d7 0%, #0f56bc 100%);
    color: #fff;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: lowercase;
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.35);
}

.invoice-layout-grid {
    display: grid;
    grid-template-columns: minmax(0, 1.2fr) minmax(0, 1.3fr) 180px;
    gap: 14px;
    align-items: start;
}

.invoice-client-selector {
    margin-bottom: 16px;
    padding: 18px;
    border: 1px solid #a6b9cd;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.52);
}

.invoice-client-selector-head {
    margin-bottom: 12px;
}

.invoice-client-table-wrap {
    max-height: 260px;
    overflow: auto;
}

.invoice-panel,
.invoice-observation-box,
.invoice-lines-card,
.invoice-payment-box,
.invoice-total-box {
    border: 1px solid #a6b9cd;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.9);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9);
}

.invoice-panel {
    padding: 12px;
}

.invoice-panel-grid {
    display: grid;
    gap: 10px 12px;
}

.invoice-panel-grid-left,
.invoice-panel-grid-right {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}

.invoice-panel-grid-right label:first-child,
.invoice-panel-grid-right label:nth-child(5),
.invoice-observation-box label {
    grid-column: 1 / -1;
}

.invoice-panel-grid-left label:nth-child(7) {
    grid-column: 1 / -1;
}

.invoice-inline-action {
    display: grid;
    grid-template-columns: minmax(220px, 1fr) auto;
    gap: 8px;
    align-items: center;
}

.invoice-inline-action input {
    width: 100%;
    min-width: 220px;
}

.invoice-inline-action-btn {
    white-space: nowrap;
}

#orderCreateGlobalDiscount {
    min-width: 220px;
    width: 100%;
}

#orderCreateApplyDiscountBtn {
    min-width: 170px;
}

#orderCreateGlobalDiscount.invoice-price-toolbar-input {
    min-width: 170px;
    flex-basis: 170px;
}

.invoice-panel-reset-client {
    margin-top: 20px;
    padding-left: 4px;
    justify-content: flex-start;
}

.invoice-side-summary {
    display: grid;
    gap: 10px;
}

.invoice-side-box {
    padding: 12px 14px;
    border: 1px solid #9fb5ca;
    border-radius: 10px;
    background: linear-gradient(180deg, rgba(240, 246, 255, 0.98) 0%, rgba(224, 235, 249, 0.98) 100%);
}

.invoice-side-box span {
    display: block;
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    color: #4c6787;
    letter-spacing: 0.04em;
}

.invoice-side-box strong {
    display: block;
    margin-top: 4px;
    font-size: 1.1rem;
    color: #19395f;
}

.invoice-observation-box {
    padding: 12px;
}

.invoice-observation-box textarea,
.invoice-workspace input,
.invoice-workspace select {
    width: 100%;
    border-radius: 6px;
    border: 1px solid #9eb3cb;
    background: #fff;
    padding: 8px 10px;
    font-size: 0.95rem;
    color: #15304d;
    box-shadow: inset 0 1px 2px rgba(15, 23, 42, 0.05);
}

.invoice-observation-box textarea {
    resize: vertical;
    min-height: 74px;
}

.invoice-workspace label {
    display: flex;
    flex-direction: column;
    gap: 6px;
    font-size: 0.78rem;
    font-weight: 700;
    color: #48627f;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

.invoice-search-label {
    position: relative;
}

.invoice-search-hero {
    padding: 18px 18px 10px;
}

.invoice-price-toolbar {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 14px;
}

.invoice-price-toolbar-input {
    flex: 0 0 190px;
    min-height: 52px;
    font-size: 1rem;
    font-weight: 700;
}

.invoice-price-toolbar-btn {
    min-height: 52px;
    padding-inline: 20px;
}

.invoice-search-label-hero {
    width: 100%;
    max-width: none;
}

.invoice-search-combo {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    width: 100%;
}

.invoice-search-topbar {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 220px;
    gap: 12px;
    align-items: stretch;
}

.invoice-search-filter {
    min-height: 74px;
    font-size: 1rem;
    font-weight: 700;
    border-radius: 26px !important;
    padding: 18px 18px 18px 20px !important;
    border: 2px solid rgba(134, 196, 201, 0.55) !important;
    background: rgba(255, 255, 255, 0.95) !important;
    box-shadow: 0 18px 40px rgba(94, 132, 154, 0.10);
    color: #183b63;
}

.invoice-search-select {
    width: 100%;
    min-height: 74px;
    font-size: 1.18rem;
    font-weight: 700;
    border-radius: 0 0 26px 26px !important;
    padding: 18px 18px 18px 20px !important;
    border: 2px solid rgba(134, 196, 201, 0.55) !important;
    border-top: 0 !important;
    background: rgba(255, 255, 255, 0.95) !important;
    box-shadow: 0 18px 40px rgba(94, 132, 154, 0.10);
    color: #183b63;
}

.invoice-search-autocomplete {
    display: grid;
    gap: 0;
    border: 2px solid rgba(134, 196, 201, 0.55);
    border-top: 0;
    border-radius: 0 0 26px 26px;
    background: rgba(255, 255, 255, 0.98);
    box-shadow: 0 18px 40px rgba(94, 132, 154, 0.10);
    overflow: hidden;
}

.invoice-search-autocomplete-item,
.invoice-search-autocomplete-empty {
    width: 100%;
    padding: 14px 20px;
    text-align: left;
    border: 0;
    border-top: 1px solid rgba(134, 196, 201, 0.18);
    background: transparent;
}

.invoice-search-autocomplete-item {
    cursor: pointer;
}

.invoice-search-autocomplete-item strong {
    display: block;
    color: #183b63;
    font-size: 1rem;
}

.invoice-search-autocomplete-item span,
.invoice-search-autocomplete-empty {
    color: #5a6d85;
    font-size: 0.92rem;
}

.invoice-search-autocomplete-item:hover,
.invoice-search-autocomplete-item:focus {
    background: rgba(135, 197, 201, 0.12);
    outline: none;
}

.invoice-search-input-hero {
    min-height: 74px;
    font-size: 1.18rem;
    font-weight: 700;
    border-radius: 26px !important;
    padding: 18px 24px !important;
    border: 2px solid rgba(134, 196, 201, 0.55) !important;
    background: rgba(255, 255, 255, 0.95) !important;
    box-shadow: 0 18px 40px rgba(94, 132, 154, 0.10);
}

.invoice-search-input-combo {
    border-radius: 26px !important;
    padding-left: 22px !important;
}

.invoice-search-input-hero:focus {
    border-color: #87c5c9 !important;
    box-shadow: 0 0 0 5px rgba(135, 197, 201, 0.14), 0 18px 36px rgba(94, 132, 154, 0.14) !important;
}

.invoice-search-select:focus {
    border-color: #87c5c9 !important;
    box-shadow: 0 0 0 5px rgba(135, 197, 201, 0.14), 0 18px 36px rgba(94, 132, 154, 0.14) !important;
    position: relative;
    z-index: 1;
}

.invoice-workspace input[readonly] {
    background: #eef3f8;
    color: #5a6d85;
}

.invoice-line-entry {
    display: grid;
    grid-template-columns: repeat(9, minmax(90px, 1fr));
    gap: 10px;
    padding: 12px;
    border-bottom: 1px solid #c8d5e4;
    align-items: end;
}

.invoice-workspace-sheet.is-wholesale .invoice-line-entry {
    display: flex;
    flex-wrap: nowrap;
    gap: 10px;
    overflow-x: auto;
    align-items: flex-end;
}

.invoice-workspace-sheet.is-wholesale .invoice-line-entry label {
    flex: 0 0 140px;
    min-width: 140px;
}

.invoice-workspace-sheet.is-wholesale .invoice-line-entry label:nth-child(3) {
    flex-basis: 160px;
    min-width: 160px;
}

.invoice-workspace-sheet.is-wholesale .invoice-line-entry label:nth-child(5) {
    flex-basis: 120px;
    min-width: 120px;
}

.invoice-workspace-sheet.is-wholesale .invoice-line-entry .invoice-add-line-btn {
    flex: 0 0 170px;
}

.invoice-add-line-btn {
    min-height: 42px;
    align-self: end;
}

#orderSelectPriceBtn.is-active {
    background: #176b63;
    border-color: #176b63;
    color: #fff;
}

@media (max-width: 768px) {
    .invoice-price-toolbar {
        flex-direction: column;
        align-items: stretch;
    }

    .invoice-price-toolbar-input {
        flex-basis: auto;
        width: 100%;
    }

    .invoice-price-toolbar-btn {
        width: 100%;
    }

    .invoice-search-select {
        border-top: 0 !important;
        border-radius: 0 0 26px 26px !important;
    }

    .invoice-search-input-combo {
        border-radius: 26px 26px 0 0 !important;
    }
}

#orderCreateProduct.is-expanded {
    min-height: 210px;
    border-color: #6aa3d8;
    box-shadow: 0 0 0 3px rgba(106, 163, 216, 0.12);
}

.product-autocomplete {
    position: relative;
    margin-top: 14px;
    max-height: 460px;
    overflow-y: auto;
    border: 1px solid rgba(190, 212, 222, 0.9);
    border-radius: 24px;
    background: rgba(255, 255, 255, 0.98);
    box-shadow: 0 28px 60px rgba(124, 150, 167, 0.18);
    padding: 10px 0;
}

.product-autocomplete-item {
    width: 100%;
    border: 0;
    background: transparent;
    text-align: left;
    padding: 18px 26px;
    border-radius: 0;
    display: flex;
    flex-direction: column;
    gap: 8px;
    color: #213047;
}

.product-autocomplete-item strong {
    font-size: 1.02rem;
    font-weight: 800;
    letter-spacing: -0.01em;
}

.product-autocomplete-item span {
    font-size: 0.84rem;
    color: #91a0b8;
    text-transform: uppercase;
}

.product-autocomplete-item:hover,
.product-autocomplete-item.is-active {
    background: rgba(236, 246, 255, 0.8);
}

.product-autocomplete-empty {
    padding: 20px 26px;
    color: #58708d;
    font-size: 0.92rem;
    font-weight: 600;
}

.invoice-lines-table-wrap {
    background: #fff;
}

.invoice-lines-table {
    min-width: 1300px;
}

.invoice-lines-table th {
    background: #dce7f4;
    color: #37597f;
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

.invoice-lines-table td {
    background: rgba(255, 255, 255, 0.98);
    font-size: 0.9rem;
}

.invoice-bottom-grid {
    display: grid;
    grid-template-columns: minmax(0, 1.2fr) minmax(340px, 0.95fr);
    gap: 14px;
    align-items: start;
}

.invoice-payment-box,
.invoice-total-box {
    padding: 12px;
}

.invoice-payment-tabs {
    display: inline-flex;
    gap: 8px;
    margin-bottom: 12px;
    padding: 5px;
    border-radius: 999px;
    background: #edf3f9;
    border: 1px solid #bfd0e0;
}

.invoice-payment-tabs span {
    padding: 6px 12px;
    border-radius: 999px;
    font-size: 0.78rem;
    font-weight: 700;
    color: #5a7290;
}

.invoice-payment-tabs .is-active {
    background: #fff;
    color: #1b3c61;
    box-shadow: 0 1px 2px rgba(17, 24, 39, 0.08);
}

.invoice-payment-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px 12px;
}

.invoice-total-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px 12px;
}

.invoice-total-grid div {
    padding: 10px 12px;
    border-radius: 10px;
    border: 1px solid #c7d6e6;
    background: linear-gradient(180deg, #ffffff 0%, #edf4fb 100%);
}

.invoice-total-grid span {
    display: block;
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    color: #57718f;
    letter-spacing: 0.03em;
}

.invoice-total-grid strong {
    display: block;
    margin-top: 5px;
    font-size: 1.15rem;
    color: #17395d;
}

.invoice-total-grid div:last-child {
    border-color: #f2b85b;
    background: linear-gradient(180deg, #fffaf0 0%, #ffe8be 100%);
}

.invoice-total-grid div:last-child strong {
    color: #c53e00;
}

.invoice-total-footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 12px;
    margin-top: 14px;
}

.invoice-lines-table .table-inline-input {
    min-width: 78px;
    border-radius: 6px;
    border: 1px solid #9eb3cb;
    padding: 7px 8px;
    font-size: 0.85rem;
    background: #fff;
}

[data-theme="dark"] .invoice-workspace-sheet {
    background: linear-gradient(180deg, rgba(17, 26, 39, 0.98) 0%, rgba(14, 22, 34, 0.98) 100%);
    border-color: #385270;
}

[data-theme="dark"] .invoice-panel,
[data-theme="dark"] .invoice-observation-box,
[data-theme="dark"] .invoice-lines-card,
[data-theme="dark"] .invoice-payment-box,
[data-theme="dark"] .invoice-total-box,
[data-theme="dark"] .invoice-side-box,
[data-theme="dark"] .invoice-total-grid div {
    background: rgba(17, 24, 39, 0.92);
    border-color: #324154;
}

[data-theme="dark"] .invoice-workspace label,
[data-theme="dark"] .invoice-side-box span,
[data-theme="dark"] .invoice-total-grid span,
[data-theme="dark"] .invoice-payment-tabs span,
[data-theme="dark"] .invoice-lines-table th {
    color: #93b4d8;
}

[data-theme="dark"] .invoice-workspace input,
[data-theme="dark"] .invoice-workspace select,
[data-theme="dark"] .invoice-observation-box textarea,
[data-theme="dark"] .invoice-lines-table .table-inline-input {
    background: #0e1724;
    border-color: #334155;
    color: #e5edf7;
}

[data-theme="dark"] .invoice-workspace input[readonly] {
    background: #131d2a;
    color: #9fb3c9;
}

[data-theme="dark"] .invoice-payment-tabs {
    background: #101927;
    border-color: #334155;
}

@media (max-width: 1280px) {
    .invoice-layout-grid,
    .invoice-bottom-grid {
        grid-template-columns: 1fr;
    }

    .invoice-line-entry {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@media (max-width: 900px) {
    .invoice-panel-grid-left,
    .invoice-panel-grid-right,
    .invoice-payment-grid,
    .invoice-total-grid,
    .invoice-line-entry {
        grid-template-columns: 1fr;
    }

    .invoice-line-filters-meta {
        flex-direction: column;
        align-items: stretch;
    }

    .invoice-total-footer,
    .invoice-software-head,
    .invoice-inline-action {
        flex-direction: column;
        align-items: stretch;
    }

    .invoice-search-topbar {
        grid-template-columns: 1fr;
    }

    .invoice-inline-action {
        display: grid;
        grid-template-columns: 1fr;
    }

    #orderCreateApplyDiscountBtn {
        width: 100%;
    }
}
